function Config.GetDataStoreName(isStudio)
	return isStudio and "ChestChasePlayerData_Studio_v1" or "ChestChasePlayerData_v1"
end

Config.BiomeNames = {
	"Sunny Meadows 🌲", "Golden Desert 🌵", "Frostland ❄️",
	"Ember Wastes 🌋", "Crystal Wilds 💎",
}

-- Stable IDs are shared by inventory, discovery, and the replicated catalog.
function Config.GetSeedById(seedId)
	if type(seedId) ~= "string" then return nil end
	for stage, catalog in ipairs(Config.SeedCatalogByStage) do
		for index, seed in ipairs(catalog) do
			if seed.Id == seedId then return seed, stage, index end
		end
	end
	return nil
end

function Config.GetSeedDefinition(stage, seedIndex)
	local normalizedStage = math.clamp(math.floor((tonumber(stage) or 1) + 0.5), 1, #Config.SeedCatalogByStage)
	local catalog = Config.SeedCatalogByStage[normalizedStage]
	local normalizedIndex = math.clamp(math.floor((tonumber(seedIndex) or 1) + 0.5), 1, #catalog)
	return catalog[normalizedIndex]
end

function Config.GetWalkSpeed(speedStat)
 return require(game:GetService('ReplicatedStorage').Progression81).Speed(speedStat)
end

function Config.GetPlayerWalkSpeed(player,speedStat)
    -- Server-private owner overrides leave saved training points unchanged.
    local temporary=require(script.Parent.OwnerTestState82).GetSpeed(player)
    if temporary then return temporary end
    local override=player and player:GetAttribute('StudioMovementSpeedOverride')
    if game:GetService('RunService'):IsStudio()and type(override)=='number'and override==override and math.abs(override)<math.huge then
        return math.clamp(override,Config.BaseWalkSpeed,500)
    end
    return Config.GetWalkSpeed(speedStat)
end

function Config.NormalizeSpeedStat(value)
 return require(game:GetService('ReplicatedStorage').SpeedPoints).Normalize(value)
end

-- Keep multiplier fractions internally, but only ever award whole points.
-- Splitting one second into more ticks never increases the total award.
function Config.GetTrainingAward(remainder, multiplier, ticks)
	local raw = (remainder or 0)
		+ Config.TrainingPointsPerSecond * Config.TrainingInterval * multiplier * ticks
	local whole = math.floor((raw + 0.0000001) / 5) * 5
	return whole, math.max(0, raw - whole)
end

local function smoothRange(value, lower, upper)
	local t = math.clamp((value - lower) / (upper - lower), 0, 1)
	return t * t * (3 - 2 * t)
end

-- R49: stage-scaled close pursuit, with bounded catch-up and a small running escape margin.
local Pursuit=require(game:GetService('ReplicatedStorage'):WaitForChild('KeeperPursuit'))
function Config.GetGuardianChaseSpeed(settings, playerSpeed, distance, stage, observedSpeed)
 return Pursuit.Speed(settings,playerSpeed,distance,stage,observedSpeed)
end

function Config.SmoothGuardianSpeed(current, target, deltaTime)
	return Pursuit.Smooth(current,target,deltaTime)
end

function Config.LegacySpeedToStat(legacySpeed)
	local legacyProgress = math.clamp(
		((tonumber(legacySpeed) or Config.BaseWalkSpeed) - Config.BaseWalkSpeed)
			/ (Config.LegacyMaxTrainedSpeed - Config.BaseWalkSpeed),
		0,
		1
	)
	return math.floor(
		Config.LegacyMigrationMaxStat * (legacyProgress ^ 2) + 0.5
	)
end

function Config.Validate()
	assert(Config.DefaultSpeed >= 0, "DefaultSpeed cannot be negative")
	assert(Config.MaxTrainedSpeed==nil, "R81 has no designed point cap")
	assert(Config.BaseWalkSpeed > 0, "BaseWalkSpeed must be positive")
	assert(Config.MaxWalkSpeed==nil, "R81 has no designed movement cap")
    assert(Config.SpeedMilestones[1][1]==Config.DefaultSpeed and Config.SpeedMilestones[1][2]==Config.BaseWalkSpeed,"Speed curve must start at the default")
    for i=2,#Config.SpeedMilestones do
        local a,b=Config.SpeedMilestones[i-1],Config.SpeedMilestones[i]
        assert(b[1]>a[1] and b[2]>a[2],"Speed milestones must increase")
    end
    local last=Config.SpeedMilestones[#Config.SpeedMilestones]
    assert(last[1]==100000000000 and last[2]==500,"R88 diminishing tail must start at 100B / 500")
    assert(require(game:GetService('ReplicatedStorage').BalanceValues81).SpeedTailPerDecade==.1,"R88 tail must remain +0.1 speed per decade")
	assert(Config.MaxHorizontalVelocityMultiplier >= 1, "MaxHorizontalVelocityMultiplier must be at least 1")
	assert(Config.TrainingInterval >= 0.1 and Config.TrainingInterval <= 1,
		"TrainingInterval must be between 0.1 and 1 second")
	assert(Config.TrainingPointsPerSecond * Config.TrainingInterval >= 1,
		"Each base training tick must award at least one whole point")
	assert(Config.TreadmillAnimationSpeed > 0 and Config.TreadmillAnimationSpeed <= 10,
		"TreadmillAnimationSpeed must be between 0 and 10")
	assert(Config.TreadmillReentryCooldown >= 0, "Reentry cooldown cannot be negative")
	assert(Config.TreadmillPopupLifetime >= 0.5 and Config.TreadmillPopupLifetime <= 2,
		"Popup lifetime must be between 0.5 and 2 seconds")
	assert(type(Config.StopTreadmillRemote) == "string", "StopTreadmillRemote must be a string")
	assert(type(Config.SpeedGainPopupRemote) == "string", "SpeedGainPopupRemote must be a string")
	assert(type(Config.ChestRunAlertRemote) == "string", "ChestRunAlertRemote must be a string")
	assert(type(Config.GuardianAlertSoundId) == "string", "GuardianAlertSoundId must be a string")
	if Config.GuardianAlertSoundId ~= "" then
		assert(
			string.match(Config.GuardianAlertSoundId, "^rbxassetid://%d+$") ~= nil,
			"GuardianAlertSoundId must look like rbxassetid://123456789"
		)
	end
	assert(
		Config.GuardianAlertVolume >= 0 and Config.GuardianAlertVolume <= 0.35,
		"GuardianAlertVolume must stay between 0 and 0.35"
	)
	assert(type(Config.ChestAlarmSoundId) == "string", "ChestAlarmSoundId must be a string")
	assert(
		Config.ChestAlarmVolume >= 0 and Config.ChestAlarmVolume <= 0.35,
		"ChestAlarmVolume must stay between 0 and 0.35"
	)
	assert(Config.AutosaveInterval >= 30, "AutosaveInterval must be at least 30 seconds")
	assert(Config.ChaserCatchupDistance > 0, "ChaserCatchupDistance must be positive")
	assert(Config.GuardianCloseDistance > Config.ChaserCatchDistance, "Close range must exceed catch range")
	assert(Config.GuardianNormalDistance > Config.GuardianCloseDistance, "Normal range must exceed close range")
	assert(Config.ChaserCatchupDistance > Config.GuardianNormalDistance, "Catchup range must exceed normal range")
	assert(Config.GuardianCatchupFullDistance > Config.ChaserCatchupDistance, "Full catchup range must exceed start")
	assert(Config.GuardianCloseSpeedMultiplier > 0 and Config.GuardianCloseSpeedMultiplier < 1, "Close multiplier must be between 0 and 1")
	assert(Config.GuardianFarSpeedMultiplier >= 1 and Config.GuardianFarSpeedMultiplier <= 1.5, "Far multiplier must be between 1 and 1.5")
	assert(Config.GuardianSpeedResponse > 0, "Guardian speed response must be positive")
	assert(Config.ChaseEffectsUpdateInterval >= 0.1, "Chase effect updates cannot exceed ten/sec")
	assert(Config.ChaseHeartbeatDistance > Config.ChaserCatchDistance, "Heartbeat distance must exceed catch range")
	assert(Config.ChaseHeartbeatMaxVolume >= 0 and Config.ChaseHeartbeatMaxVolume <= 0.25, "Heartbeat volume must stay quiet")
	assert(Config.ChaseHeartbeatSoundId == "" or string.match(Config.ChaseHeartbeatSoundId, "^rbxassetid://%d+$"), "Invalid heartbeat asset ID")
	assert(Config.ChaseSuccessSoundId == "" or string.match(Config.ChaseSuccessSoundId, "^rbxassetid://%d+$"), "Invalid success sound asset ID")
	assert(Config.ChaseSuccessSoundVolume >= 0 and Config.ChaseSuccessSoundVolume <= 0.35, "Success sound must stay quiet")
	assert(Config.ChaseSuccessFlashStrength >= 0 and Config.ChaseSuccessFlashStrength <= 0.5, "Success flash cannot obscure the HUD")
	assert(Config.ChaseSuccessFlashDuration >= 0.4 and Config.ChaseSuccessFlashDuration <= 2, "Success flash duration must stay brief")
	assert(Config.DroppedChestDuration > 0, "DroppedChestDuration must be positive")
	assert(
		Config.DroppedChestClaimGrace >= 0 and Config.DroppedChestClaimGrace <= 1,
		"DroppedChestClaimGrace must stay between 0 and 1 second"
	)
	assert(
		Config.DroppedChestGuardianRestartDistance > Config.ChaserCatchDistance,
		"DroppedChestGuardianRestartDistance must exceed ChaserCatchDistance"
	)
	assert(Config.GuardianFlingProtectionTime > 0, "GuardianFlingProtectionTime must be positive")
	assert(Config.GuardianNoticeDelay >= 0, "GuardianNoticeDelay cannot be negative")
	assert(Config.GuardianRagdollMinDuration >= 0.4, "GuardianRagdollMinDuration must be at least 0.4")
	assert(
		Config.GuardianRagdollMaxDuration >= Config.GuardianRagdollMinDuration
			and Config.GuardianRagdollMaxDuration <= 2,
		"GuardianRagdollMaxDuration must be between the minimum and 2 seconds"
	)
	assert(Config.PassiveCashTickSeconds > 0, "PassiveCashTickSeconds must be positive")

	local seenSeedIds = {}
	for stage = 1, Config.StageCount do
		local entries = Config.LootChancesByStage[stage]
		assert(entries, string.format("[%s] Missing loot chances for stage %d", Config.Version, stage))
		local guardian = Config.GuardianSettingsByStage[stage]
		assert(
			type(guardian) == "table",
			string.format("[%s] Missing guardian settings for stage %d", Config.Version, stage)
		)
		assert(guardian.MinimumSpeed > 0, "Guardian MinimumSpeed must be positive")
		assert(
			guardian.PlayerSpeedRatio > 0 and guardian.PlayerSpeedRatio < 1,
			"Guardian PlayerSpeedRatio must stay between 0 and 1"
		)
		assert(guardian.CatchupBonus >= 0, "Guardian CatchupBonus cannot be negative")
		assert(guardian.FlingHorizontal > 0, "Guardian FlingHorizontal must be positive")
		assert(guardian.FlingVertical >= 0, "Guardian FlingVertical cannot be negative")
		assert(
			guardian.RagdollDuration >= 0.4 and guardian.RagdollDuration <= 2,
			"Guardian RagdollDuration must stay between 0.4 and 2 seconds"
		)

		local totalChance = 0
		for _, entry in ipairs(entries) do
			assert(Config.LootItemsByRarity[entry.Rarity], "Unknown rarity: " .. tostring(entry.Rarity))
			totalChance = totalChance + entry.Chance
		end
		assert(totalChance == 100, string.format("Stage %d reward chances must total 100", stage))

		local seedCatalog = Config.SeedCatalogByStage[stage]
		assert(type(seedCatalog) == "table" and #seedCatalog == 8,
			string.format("Stage %d must define exactly eight seeds", stage))
		for _, seed in ipairs(seedCatalog) do
			assert(type(seed.Id) == "string" and seed.Id ~= "", "Seed Id cannot be empty")
			assert(not seenSeedIds[seed.Id] or (Config.StageSeedPools and Config.StageSeedPools[stage] and seedCatalog == Config.SeedCatalogByStage[Config.StageSeedPools[stage]]), "Duplicate seed Id: " .. seed.Id)
			seenSeedIds[seed.Id] = true
			assert(type(seed.Name) == "string" and seed.Name ~= "", "Seed Name cannot be empty")
			assert(type(seed.Emoji) == "string" and seed.Emoji ~= "", "Seed Emoji cannot be empty")
			assert(seed.Color ~= nil, "Seed Color cannot be missing")
		end
	end

	local seenProductIds = {}
	for category, products in pairs(Config.ShopCatalog) do
		assert(type(products) == "table" and #products > 0, "Empty shop category: " .. tostring(category))
		for _, product in ipairs(products) do
			assert(not seenProductIds[product.Id], "Duplicate shop product: " .. tostring(product.Id))
			seenProductIds[product.Id] = true
			if product.Enabled == false then
				assert(product.Price >= 0, "Disabled products cannot have a negative price")
			else
				assert(product.Price > 0, "Enabled shop products must have a positive Cash price")
			end
			if product.Type == "Trail" then
				assert(product.SpeedMultiplier and product.SpeedMultiplier >= 1, "Trail is missing SpeedMultiplier")
			elseif product.Type == "Accessory" then
				assert(product.LuckMultiplier and product.LuckMultiplier >= 1, "Accessory is missing LuckMultiplier")
			elseif product.Type == "Gear" then
				assert(product.Enabled == false, "Gear must stay disabled until its gameplay exists")
			else
				error("Unknown shop product type: " .. tostring(product.Type))
			end
		end
	end
end
