Config.GardenGrowthThresholds = {0.1, 0.45, 1}

function Config.IsFiniteGardenNumber(value)
	return type(value) == "number" and value == value and math.abs(value) < math.huge
end

-- Pure XZ geometry shared by decoding and the non-yielding commit path.
-- Width/depth are derived from server-owned parts for live requests.
function Config.ValidateGardenPlacement(crops, x, z, width, depth, legacySpacing)
	if not Config.IsFiniteGardenNumber(x) or not Config.IsFiniteGardenNumber(z)
		or not Config.IsFiniteGardenNumber(width) or not Config.IsFiniteGardenNumber(depth) then
		return false, "INVALID PLANT POSITION"
	end
	if math.abs(x) > width / 2 - Config.GardenPlotEdgePadding
		or math.abs(z) > depth / 2 - Config.GardenPlotEdgePadding then
		return false, "PLANT A LITTLE FARTHER FROM THE EDGE"
	end
	for _, crop in ipairs(crops) do
		local dx, dz = x - crop.OffsetX, z - crop.OffsetZ
		if dx * dx + dz * dz < (legacySpacing or Config.GardenMinimumPlantSpacing) ^ 2 then
			return false, "LEAVE MORE ROOM BETWEEN PLANTS"
		end
	end
	return true
end

-- Security bound only: cells have a diagonal smaller than minimum spacing,
-- so two valid centers cannot occupy one cell. This never limits valid packing.
function Config.GardenStorageBound(width, depth)
    local cell = Config.GardenMinimumPlantSpacing / math.sqrt(2) * 0.99
    local x = math.max(0, width - 2 * Config.GardenPlotEdgePadding)
    local z = math.max(0, depth - 2 * Config.GardenPlotEdgePadding)
    return (math.floor(x / cell) + 1) * (math.floor(z / cell) + 1)
end

function Config.GetGardenGrowth(crop, now)
	local duration = math.max(1, crop.ReadyAt - crop.PlantedAt)
	local progress = math.clamp((now - crop.PlantedAt) / duration, 0, 1)
	local stage = progress >= Config.GardenGrowthThresholds[3] and 4 or (progress >= Config.GardenGrowthThresholds[2] and 3 or (progress >= Config.GardenGrowthThresholds[1] and 2 or 1))
	return progress, stage, math.max(0, math.ceil(crop.ReadyAt - now))
end

for _, seeds in ipairs(Config.SeedCatalogByStage) do
	for _, seed in ipairs(seeds) do
		local growing = Config.GardenPlants[seed.Id]
		assert(growing and growing.Seconds >= 1 and growing.Value >= 1, "Missing garden tuning for "..seed.Id)
	end
end

-- V0.76 compact garden-toy model definitions. Generated from author_assets.py.
local function unpackParts(packed)
	local output = {}
	for index, value in ipairs(packed) do
		output[index] = {
			n = value[1], s = {value[2], value[3], value[4]},
			p = {value[5], value[6], value[7]}, c = {value[8], value[9], value[10]},
			k = value[11], r = {value[12] or 0, value[13] or 0, value[14] or 0},
			g = value[15] or "Body", t = value[16] or "", m = value[17] or "SmoothPlastic",
		}
	end
	return output
end
