Config.BiomeNames[8]='Mech';Config.BiomeRank[8]=8
local validateBase=Config.Validate
function Config.Validate()
 validateBase()
 local mech=require(game:GetService('ReplicatedStorage').MechCatalog)
 local ids,total={},0
 assert(Config.StageCount==7 and #Config.SeedCatalogByStage[8]==6,'Invalid limited seed category')
 for _,seed in ipairs(mech.Seeds)do
  assert(not ids[seed.Id] and Config.GetSeedById(seed.Id),'Invalid limited seed identity');ids[seed.Id]=true
  assert(type(seed.Chance)=='number'and seed.Chance>0 and seed.Chance<=100,'Invalid limited seed chance');total+=seed.Chance
  local plant=Config.GardenPlants[seed.Id]
  assert(plant and plant.Mech and plant.FruitCount==#plant.Sockets and plant.Value>0,'Invalid mech plant')
 end
 assert(math.abs(total-100)<.000001,'Limited seed chances must total 100%')
end
